        concepts: [
          { h: "常見非文學文本及分析重點", b: "<table><tr><th>文本類型</th><th>分析重點</th></tr><tr><td>廣告／海報</td><td>標語、圖文關係、色彩與構圖、目標受眾、說服策略（情感、權威、從眾）</td></tr><tr><td>社論／評論</td><td>立場、論證結構、論據（數據、例子、引用）、語氣、反駁</td></tr><tr><td>新聞報道</td><td>標題、導語、倒金字塔結構、消息來源、客觀性與取捨</td></tr><tr><td>演講稿</td><td>稱呼、排比、設問、呼告、節奏、情感高潮、呼籲行動</td></tr><tr><td>漫畫</td><td>誇張、象徵、對話框、諷刺對象、圖文反差</td></tr><tr><td>資訊圖表</td><td>數據呈現方式、視覺層次、色彩編碼、簡化與誤導</td></tr><tr><td>網誌／社交媒體</td><td>口語化、個人化語氣、互動性、表情符號、標籤</td></tr></table>" },
          { h: "說服策略（亞里士多德三要素）", b: "<p><strong>訴諸理性 (logos)</strong>：數據、邏輯、事實。<strong>訴諸情感 (pathos)</strong>：感人故事、恐懼、懷舊。<strong>訴諸人格／權威 (ethos)</strong>：專家、名人、品牌信譽。</p>" },
        ],
        terms: [["標語", "廣告中簡短而易記的口號。"], ["倒金字塔結構", "新聞報道把最重要的資訊放在最前面，細節依次在後。"], ["訴諸情感", "利用讀者的情緒（同情、恐懼、自豪）來說服。"], ["多模態文本", "結合文字、圖像、聲音等多種表達方式的文本。"]],
        examples: [{ q: "分析一則防疫海報「一個口罩，守護一家」的說服策略。", a: "標語運用對比（「一個」與「一家」）突出個人行為的巨大影響；訴諸情感（保護家人），配以溫暖色調的全家福圖像，令受眾產生責任感而自發佩戴口罩。" }],
        questions: [
          { type: "mcq", paper: "測驗", marks: 1, diff: 1, q: "新聞報道把最重要資訊放在第一段，稱為：", options: ["倒敘法", "倒金字塔結構", "首尾呼應", "層遞"], answer: 1, ms: ["新聞的倒金字塔結構。"] },
          { type: "mcq", paper: "測驗", marks: 1, diff: 2, q: "廣告請來醫生代言牙膏，主要運用了哪種說服策略？", options: ["訴諸情感", "訴諸權威／人格", "訴諸從眾", "訴諸恐懼"], answer: 1, ms: ["專業人士代言 = 訴諸權威 (ethos)。"] },
          { type: "short", paper: "練習", marks: 4, diff: 2, q: "比較社論與新聞報道在立場、語氣及結構上的分別。", ms: ["社論有明確立場；新聞報道力求客觀中立", "社論語氣具說服力／評論性；新聞語氣平實", "社論以論點—論據—結論組織；新聞採倒金字塔結構", "能舉例或說明不同寫作目的"] },
          { type: "extended", paper: "P1", marks: 20, diff: 2, q: "<strong>閱讀以下廣告文案（原創練習文本）：</strong><blockquote>【慢一點，也很好】<br>城市的步伐太快，連早餐也要邊走邊吃。<br>這個週末，關掉通知，來我們的山邊小館，<br>喝一碗熬了六小時的白粥。<br>有些味道，急不來。<br>—— 半山小館　預約熱線：[電話]</blockquote><strong>引導問題：</strong>作者如何運用語言與結構吸引都市讀者？", ms: p1ms(["指出「快／慢」的對比貫穿全文，呼應標題", "分析短句與分行製造緩慢節奏，模仿「慢」的生活", "分析祈使句（「關掉通知」）與第二人稱的親切感", "分析「熬了六小時」的細節與「有些味道，急不來」的雙關（食物／人生）", "連繫目標受眾（忙碌都市人）及說服策略（訴諸情感）"]) },
        ],
